"""Seal tested projection audit. Read own derived outputs only, no rerun."""
from pathlib import Path
import ast,hashlib,json,math,re
import numpy as np
R=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def new(p,v):assert not p.exists(),str(p);p.write_text(json.dumps(v,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def meta(p):return {'path':str(p),'relative':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'SHA':sha(p)}
def stats(x):
    a=np.asarray(x,float);return {'absolute_axis_p50_p95_max':np.percentile(abs(a),[50,95,100],axis=0).tolist()}
def scalar_stats(x):
    a=np.asarray(x,float);return {'n':len(a),'p50':float(np.median(a)),'p95':float(np.percentile(a,95)),'max':float(a.max())}
def main():
    assert not (R/'INDEX.json').exists()
    attempt=R/'attempts/001';check=json.loads((attempt/'RESULT.json').read_text(encoding='utf-8'));summary=json.loads((attempt/'audit/SUMMARY.json').read_text(encoding='utf-8'))
    assert check['all_passed'] and check['units']['tests']==14 and summary['total_rows']==4400
    for s in check['source_files']:assert sha(R/s['name'])==s['SHA'],'tested source changed'
    for p,h in check['protected_hashes'].items():assert sha(Path(p))==h,'sealed dependency/projection manifest changed'
    comparison=[];artifacts=[]
    for s in summary['cases']:
        p=attempt/'audit'/(s['case']+'_shadow.jsonl');rows=[json.loads(x) for x in p.read_text(encoding='utf-8').splitlines()];good=[x for x in rows if 'qdd_FD4' in x['conditional']]
        assert len(rows)==s['rows'] and all(x['strict_unbound']['cue']==0 and x['conditional']['cue']==0 for x in rows)
        dp=[];da=[]
        for x in good:
            c=x['conditional'];b=x['frozenV4_baseline'];dp.append(float(np.linalg.norm(np.array(c['proper_origin_window_center_model_B3'])-b['proper_origin_B3'])));da.append(float(np.linalg.norm(np.array(c['alpha_FD_B3'])-b['alpha_LP60ms_B3'])))
        comparison.append({'case':s['case'],'eligible_rows':len(good),'qdd_mean_center_FD':stats([x['conditional']['qdd_FD4'] for x in good]),'alpha_mean_center_FD':stats([x['conditional']['alpha_FD_B3'] for x in good]),'alphaFD_vs_frozenLP_norm_difference_rad_s2':scalar_stats(da),'properRootFD_vs_frozenLP_norm_difference_m_s2':scalar_stats(dp),'difference_is_not_error_against_truth':True,'LP_does_not_become_instantaneous_by_smaller_variance':True})
        artifacts.append({**meta(p),'artifact_role':'new_sensor_only_derived_shadow_not_original_rawtrace','producer_SHA_by_this_audit':True})
    new(R/'FROZEN_BASELINE_COMPARISON.json',{'cases':comparison,'not_truth_accuracy_or_filter_qualification':True,'original_evidence_reread':False})
    new(R/'DERIVED_OUTPUT_MANIFEST.json',{'artifacts':artifacts,'original_cases_only_sourceSHA_referenced':True,'no_original_trace_opened':True})
    new(R/'ASSUMPTIONS.json',{'strict':'No hardware calibration, jerk/curvature/zero-offset/wheel-motion error guarantee inferred from coherent epoch. UNCERTAIN.','conditional':summary['assumptions'],'public_D1_scope':summary['public_D1_source'],'same_error_assumptions_all4cases':True,'no_nominal_or_DR_receipt_parameter_selection':True,'noise_halfwidths_not_reduced_by20':summary['public_D1_halfwidths_same_allcases'],'derivative_kernel_mean_absolute_time_lag_s_at10ms':.005415625,'q_center_model':'q_end-v_mean*.00525-.5*qdd_est*.00525^2','error_radius_is_local_engineering_scale_not_global_DR_or_calibrated_probability':True,'frozen_COM_thresholds':summary['frozen_COM_config_unchanged'],'model_confidence_not_raised':True})
    new(R/'MINIMUM_CAPTURE_BINDINGS.json',{'status':'PROPOSED_MINIMUM_BINDINGS_NOT_NEW_PARENT_CODE_OR_HARDWARE_CALIBRATION','items':['Keep per-channel true acquisition/aperture begin/end/center, weights, sample sequence, arrival and duplicate state; queueepoch alone is not simultaneous input.','Either supply same-time q/qd/IMU point samples with declared filters, or same-window moments/derivative estimates with effective times and physically justified motion/jerk bounds.','Bind encoder q4 absolute output zero/sign/ratio, velocity-estimator algorithm/noise/filter/group delay, and derivative error/time model; do not infer these from a complete control run.','Bind origin-to-IMU position and orientation (.03,0,.04 is current nominal lever), proper reference and alpha used for lever compensation, all with error/latency.','Provide alpha from calibrated synchronized high-rate gyro or an explicitly delayed estimator with covariance/bounds;60ms LP is not instantaneous.','For current20sample projection retain aperture; to evaluate nonlinear corrections at center need measured/justified curvature/covariance, not only count20 and sharedtime.','For optional wheel phase use actual encoder binding; otherwise retain nominal radial-COM fullphase geometric bound plus declared wheel rate/acc errors, not a balanced-wheel assumption.','Keep truth grading separate in parent; do not use contact/root/world/DR receipts to choose these error parameters or remove missed boundaries.'],'do_not_lower_FSM_thresholds_or_force_point8':True,'H1_H2_immutable':True})
    new(R/'VALIDATION.json',{'status':'4400_SENSOR_ONLY_SHADOW_APPLICABILITY_AUDIT_PASS_TRUSTED_CUES_STILL_UNCERTAIN','units':check['units'],'source_SHA_bound_to_attempt001':True,'projection_rows':4400,'strict_trusted_vector_or_cue_rows':0,'conditional_numeric_or_bounded_rows':sum(x['conditional']['bounded_under_declared_assumptions_rows'] for x in summary['cases']),'conditional_trusted_cue_rows':0,'old_sources_unchanged':check['protected_hashes'],'source_reads':summary['evidence_reads'],'original_case_or_DR_receipt_reads':0,'physics_steps':0,'Git_newagent_hardware_IO':False,'not_hardware_or_truth_accuracy_qualification':True,'PH3pending':True})
    table=[]
    for s in summary['cases']:
        n=s['rows'];b=s['conditional'];rad=b['radius_m_s2'];table.append(f"|{s['case']}|{n}|{s['duplicate_epochs']}|{b['bounded_under_declared_assumptions_rows']}/{n} ({100*b['bounded_rate_allrows']:.3f}%)|{rad['p50']:.6f} / {rad['p95']:.6f}|0|")
    text='''# COM Sensor Capture Audit v1 — sensor-only shadow applicability\n\n**4400projection rows完整核验，14/14边界/allowlist/数学单测首次通过；0physics/Git/newagent/真实IO。严格分支与条件分支的可信cue均为0，保留UNCERTAIN，没有为通过FSM门槛删掉边界或抬高置信。**\n\n## 逐case结果\n\n“有界”只表示显式synthetic/window/model误差假设下可算局部工程radius，不是硬件可用率或准确率。\n\n|case|rows|重复epoch|条件数值/有界行（全row分母）|radius p50 / p95 m/s²|可信cue|\n|---|---:|---:|---:|---:|---:|\n'''+ '\n'.join(table)+'''\n\n严格unbound分支：4400/4400 UNCERTAIN，usable vector/cue0。条件分支共4390/4400数值/有界行（99.773%），但radius约12.16–12.53m/s²；冻结threshold不改、声明input confidence最多.50低于COM默认.60。即使忽略置信门，也没有把这些宽区间叫成可靠freefall/nonfreefall。被排除10行是4boot instant、4首次mean边界及2重复首包；不是删掉“不好看”的运动样本。\n\n## 证据与入口\n\n- [Scope](<SCOPE.md>)；[实现](<shadow_audit.py>)；[14单测](<test_shadow.py>)；[append-only runner](<run_audit.py>)。\n- [本次RESULT/sourceSHA](<attempts/001/RESULT.json>)、[原样unit log](<attempts/001/unittest.log>)、[完整逐case summary](<attempts/001/audit/SUMMARY.json>)。\n- [逐row derived输出manifest/producerSHA](<DERIVED_OUTPUT_MANIFEST.json>)、[冻结V4 baseline对照](<FROZEN_BASELINE_COMPARISON.json>)。\n- [显式假设](<ASSUMPTIONS.json>)、[最小真实采集绑定](<MINIMUM_CAPTURE_BINDINGS.json>)、[validation](<VALIDATION.json>)、[完整index](<INDEX.json>)。\n\n只读父SENSOR_CAPTURE_CLOOP_V1 manifest及四个*_sensor_only projections，原case仅引用sourceSHA。验证每个projection producerSHA/bytes/rowcount、top+nested严格allowlist；drive6速度逐项等于4joint dq＋2wheel spin拼接。没有打开完整原trace、episode DRreceipt、root/contact/真姿态/envelope。源码/依赖HASH保护均未变，旧DYNAMIC_COM/CONTACT/FSM/PH2保持封存。\n\n## 真实时钟/窗口结论\n\n- epoch t时gyro/proper/qd是20×.5ms窗口[t−.010,t−.0005]均值，支撑span9.5ms、center=t−5.25ms；q4仍是endepoch值。coherent/sharedqueueepoch仅是队列声明，**不证明瞬时同步**。\n- 无queue年龄的nominal case：mean center已比arrival旧5.25ms，相邻mean差分名义center旧10.25ms；DR101/102观察到queue年龄10ms，则分别15.25/20.25ms。没有把观测队列年龄反解为episode参数。\n- frozenV4纯sensor-math replay给sampleomega/alphaLP/properRoot作baseline，alpha60ms LP稳态effective age约70.25ms（nominal）/80.25ms（上述队列延迟），不是当前瞬时alpha。boot初始alpha0先验及instant→mean过渡另标，不赚新可靠样本。\n- instant→mean直接重置新分支差分历史；重复首包不更新alpha/qdd或持续窗。全部逐row输出保留。\n\n## 条件分支具体做了什么\n\n目标选current window center，不冒epoch瞬时。用二阶模型`q_center=q_end-v_mean*5.25ms-.5*a_fd*(5.25ms)^2`对齐q；qdd/alpha从相邻mean-center采集时差求差分，但名义导数时间仍比targetcenter早5ms。20point均值＋差分kernel对current center的E|lag|=5.415625ms，只有显式jerk假设才可传播时间误差。\n\n相同PUBLIC D1半宽用于全部4cases：gyro.125rad/s、q.005rad、qd.25rad/s、wheelqd.5rad/s；gravity3.025dimensionless映射proper乘9.81只是明示benchmark假设。D1是100Hz每feedback量加噪再D3排队，**没有将噪声÷20或÷sqrt20**。不按case的nominal/DR标签推回真实噪声开关、不读取D0–D7receipt。\n\n示例声明jerk q1000rad/s³、angular200rad/s³时，每轴qdd error约55.415625rad/s²、alpha约26.083125rad/s²；另有proper curvature/lever误差、未验证零点allowance与冻结COM model-error scale。它们是可见的工程假设，不是硬件校准，也不是保证涵盖所有模型/高阶曲率/柔顺变化的全局区间。\n\nproper atIMU先按origin→IMU lever(.03,0,.04)做`properRoot=properIMU-alpha×lever-omega×(omega×lever)`；lever与alpha误差也进预算，再调用未改的movingCOM全项补偿。wheel无phase按冻结模块完整圆周几何缺项界，rate/acc只用projection纯encoder及明示差分误差，不假balancedwheel。\n\n## 适用性结论与最小补齐\n\n新projection修好了旧R16“没有采集stamp/raw q tuple”的缺口；现在能检查采集/到达/epoch/重复与窗口。**它仍未建立可靠当前qdd/alpha和COM-cue绑定**：均值aperture、q异时、差分中点和60ms LP都仍存在，PUBLIC模拟噪声范围更不等于实机标定。数值可算率99.8%不等于可信cue可用率。\n\n最小下一步是绑定每路真实aperture/采集/到达及滤波延迟，encoder零点/速估计噪声，IMUlever/方向与alpha有效时间；要么提供同时间的instant传感器和校准导数，要么保留同window语义并提供有依据的运动/协方差/jerk界。旧冻结H1/H2不改，真值grading仍由父独立进行，不用真值来补这个shadow。\n\n本目录及所有derived reports均PH3pending；没有重record PH2或执行新物理。整体Goal继续active。\n'''
    (R/'README.md').write_text(text,encoding='utf-8')
    files=sorted(p for p in R.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='INDEX.json')
    new(R/'INDEX.json',{'module':'COM_SENSOR_CAPTURE_AUDIT_V1','status':'SHADOW_NUMERIC_COMPUTABLE_BUT_TRUSTED_CUES_UNCERTAIN','core':meta(R/'shadow_audit.py'),'README':meta(R/'README.md'),'validation':meta(R/'VALIDATION.json'),'all_attempts':['attempts/001'],'projection_only_original_sourceSHA_reference':True,'no_threshold_lowering_or_hardware_calibration_claim':True,'new_physics_steps':0,'Git_newagents_realIO':False,'PH3pending':True,'files':[meta(p) for p in files]})
    count=0
    for p in R.glob('*.md'):
        for link in re.findall(r'\]\(<([^>]+)>\)',p.read_text(encoding='utf-8')):assert (p.parent/link.split('#')[0]).exists(),(p,link);count+=1
    print(json.dumps({'core':meta(R/'shadow_audit.py'),'README':meta(R/'README.md'),'INDEX':meta(R/'INDEX.json'),'VALIDATION':meta(R/'VALIDATION.json'),'units':check['units'],'rows':4400,'conditional_numeric_bounded':4390,'trusted_cues_both_branches':0,'radius_p50_by_case':{x['case']:x['conditional']['radius_m_s2']['p50'] for x in summary['cases']},'links_checked':count,'source_protection_unchanged':True,'new_physics_steps':0,'PH3pending':True},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
